/**
 * Centralized CORS Configuration for WRFCoin Platform
 * Replaces wildcard Access-Control-Allow-Origin: * with proper origin validation
 *
 * Security: This module implements proper CORS origin validation to prevent
 * cross-origin attacks and credential leakage.
 */

import type { Request, Response, NextFunction } from 'express';
import { securityLogger } from '../../server/utils/logger.js';
// strict-cors-config.js is CJS; import the .cjs shim (generated by copy-build-assets.mjs).
import _strictCorsModule from '../../server/utils/strict-cors-config.js';
const { resolveAllowedOrigins, isExplicitlyDisallowedOrigin } =
  _strictCorsModule as { resolveAllowedOrigins: (...args: unknown[]) => string[]; isExplicitlyDisallowedOrigin: (origin: string) => boolean };

const DEFAULT_ALLOWED_ORIGINS: string[] = [
  'https://wrfcoin.replit.app',
  'https://wrfcoin.app',
  'https://www.wrfcoin.app',
  'https://api.wrfcoin.app',
  'https://dashboard.wrfcoin.app',
  'http://localhost:3000',
  'http://localhost:5000',
  'http://localhost:4001',
  'http://127.0.0.1:3000',
  'http://127.0.0.1:5000',
];

const ALLOWED_ORIGINS: string[] = resolveAllowedOrigins({
  developmentDefaults: DEFAULT_ALLOWED_ORIGINS,
});

// Replit domain patterns for dynamic subdomains
const ALLOWED_PATTERNS: RegExp[] = [
  /^https:\/\/[\w-]+\.wrfcoin\.app$/,
  /^https:\/\/[\w-]+\.replit\.app$/,
  /^https:\/\/[\w-]+\.repl\.co$/,
  /^https:\/\/[\w-]+\.replit\.dev$/,
];

// Development localhost pattern
const LOCALHOST_PATTERN = /^http:\/\/(?:localhost|127\.0\.0\.1|0\.0\.0\.0):\d+$/;

/**
 * Validates if the given origin is allowed
 * @param origin - The origin to validate
 * @returns The origin if valid, or false if not allowed
 */
export function validateOrigin(origin: string | undefined): string | false {
  if (!origin) {
    // Allow requests with no origin (same-origin, mobile apps, curl, etc.) in development
    if (process.env.NODE_ENV === 'development') {
      return '';
    }
    return false;
  }

  if (isExplicitlyDisallowedOrigin(origin)) {
    return false;
  }

  // Direct match against allowed origins
  if (ALLOWED_ORIGINS.includes(origin)) {
    return origin;
  }

  // Pattern matching for dynamic subdomains
  for (const pattern of ALLOWED_PATTERNS) {
    if (pattern.test(origin)) {
      return origin;
    }
  }

  // Allow localhost with any port in development
  if (process.env.NODE_ENV === 'development' && LOCALHOST_PATTERN.test(origin)) {
    return origin;
  }

  return false;
}

/**
 * Generates CORS headers based on the request origin
 * @param origin - The origin from the request headers
 * @returns Object containing CORS headers
 */
export function getCorsHeaders(origin: string | undefined): Record<string, string> {
  const validOrigin = validateOrigin(origin);

  if (validOrigin === false) {
    return {
      'Access-Control-Allow-Origin': '',
      'Access-Control-Allow-Methods': 'GET, POST, PUT, DELETE, OPTIONS',
      'Access-Control-Allow-Headers': 'Content-Type, Authorization, X-Requested-With, Origin, Accept, X-API-Key',
      'Access-Control-Allow-Credentials': 'false',
    };
  }

  return {
    'Access-Control-Allow-Origin': validOrigin || '',
    'Access-Control-Allow-Methods': 'GET, POST, PUT, DELETE, OPTIONS',
    'Access-Control-Allow-Headers': 'Content-Type, Authorization, X-Requested-With, Origin, Accept, X-API-Key',
    'Access-Control-Allow-Credentials': 'true',
  };
}

/**
 * Sets CORS headers on an HTTP response
 * @param res - The response object
 * @param origin - The origin from the request headers
 */
export function setCorsHeaders(res: Response, origin: string | undefined): void {
  const headers = getCorsHeaders(origin);
  Object.entries(headers).forEach(([key, value]) => {
    if (value) {
      res.setHeader(key, value);
    }
  });
}

/**
 * Express middleware for CORS handling with origin validation
 */
export function corsMiddleware(req: Request, res: Response, next: NextFunction): void {
  const origin = req.headers.origin as string | undefined;
  const validOrigin = validateOrigin(origin);

  if (validOrigin !== false) {
    setCorsHeaders(res, origin);
  } else if (origin) {
    // Log blocked origin attempts (but don't block for preflight)
    securityLogger.warn('CORS: Blocked request from unauthorized origin', { module: 'CORS', origin });
  }

  // Handle preflight requests
  if (req.method === 'OPTIONS') {
    if (validOrigin !== false || !origin) {
      res.status(200).end();
    } else {
      res.status(403).json({
        success: false,
        error: {
          code: 'CORS_ORIGIN_NOT_ALLOWED',
          message: 'Origin not allowed by CORS policy',
        },
      });
    }
    return;
  }

  next();
}

/**
 * For raw HTTP servers (non-Express), apply CORS headers to response
 * Returns false if the origin is not allowed
 * @param res - Node.js HTTP response object
 * @param origin - The origin from request headers
 * @returns true if origin is valid and headers were set, false otherwise
 */
export function applyRawCorsHeaders(
  res: { setHeader: (name: string, value: string) => void },
  origin: string | undefined
): boolean {
  const validOrigin = validateOrigin(origin);

  if (validOrigin === false && origin) {
    securityLogger.warn('CORS: Blocked request from unauthorized origin', { module: 'CORS', origin });
    return false;
  }

  const originToSet = validOrigin || '';

  if (originToSet) {
    res.setHeader('Access-Control-Allow-Origin', originToSet);
  }
  res.setHeader('Access-Control-Allow-Methods', 'GET, POST, PUT, DELETE, OPTIONS');
  res.setHeader('Access-Control-Allow-Headers', 'Content-Type, Authorization, X-Requested-With, Origin, Accept, X-API-Key');
  res.setHeader('Access-Control-Allow-Credentials', 'true');

  return true;
}

/**
 * JavaScript/CommonJS compatible version for use in .js files
 */
export const corsConfig = {
  validateOrigin,
  getCorsHeaders,
  setCorsHeaders,
  corsMiddleware,
  applyRawCorsHeaders,
  ALLOWED_ORIGINS,
};

export default corsConfig;
